-- ===========================================================================
-- PART 2: hand-written (T-005). Constraints Prisma cannot express.
-- ===========================================================================

-- users: platform admin <=> no institution; lowercase emails.
ALTER TABLE "users" ADD CONSTRAINT "users_role_institution_chk"
  CHECK (("role" = 'PLATFORM_ADMIN') = ("institution_id" IS NULL));
ALTER TABLE "users" ADD CONSTRAINT "users_email_lower_chk" CHECK ("email" = lower("email"));
ALTER TABLE "invites" ADD CONSTRAINT "invites_email_lower_chk" CHECK ("email" = lower("email"));
ALTER TABLE "credential_holders" ADD CONSTRAINT "credential_holders_email_lower_chk"
  CHECK ("email" IS NULL OR "email" = lower("email"));

-- institutions: hex colours.
ALTER TABLE "institutions" ADD CONSTRAINT "institutions_primary_color_chk"
  CHECK ("primary_color" ~ '^#[0-9a-fA-F]{6}$');
ALTER TABLE "institutions" ADD CONSTRAINT "institutions_secondary_color_chk"
  CHECK ("secondary_color" ~ '^#[0-9a-fA-F]{6}$');

-- institution_keys: at most one ACTIVE key per institution.
CREATE UNIQUE INDEX "institution_keys_one_active_per_institution"
  ON "institution_keys" ("institution_id") WHERE "status" = 'ACTIVE';

-- credentials: superseded_by is set iff status is SUPERSEDED; a credential cannot supersede itself.
ALTER TABLE "credentials" ADD CONSTRAINT "credentials_superseded_by_status_chk"
  CHECK (("superseded_by" IS NOT NULL) = ("status" = 'SUPERSEDED'));
ALTER TABLE "credentials" ADD CONSTRAINT "credentials_not_self_superseded_chk"
  CHECK ("superseded_by" IS NULL OR "superseded_by" <> "id");
ALTER TABLE "credential_types" ADD CONSTRAINT "credential_types_validity_days_chk"
  CHECK ("validity_days" IS NULL OR "validity_days" > 0);

-- Audit chains: Prisma's unique indexes treat NULL institution_id (the platform chain) as
-- distinct. These NULLS NOT DISTINCT constraints (PostgreSQL 15+) close that gap and also stop
-- two entries from sharing a predecessor (a forked chain).
ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_chain_seq_uniq"
  UNIQUE NULLS NOT DISTINCT ("institution_id", "seq");
ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_chain_prev_hash_uniq"
  UNIQUE NULLS NOT DISTINCT ("institution_id", "prev_hash");
ALTER TABLE "audit_head_hashes" ADD CONSTRAINT "audit_head_hashes_chain_day_uniq"
  UNIQUE NULLS NOT DISTINCT ("institution_id", "day");

-- sessions / password_resets: institution_id must equal the owning user's institution_id
-- (NULL for platform admins). Plain FK to users because institution_id is nullable.
-- The function runs with invoker rights, so under RLS a user from another tenant is simply
-- invisible and the insert is rejected.
CREATE FUNCTION "igaro_enforce_user_institution"() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  user_institution uuid;
  user_found boolean;
BEGIN
  SELECT true, u."institution_id" INTO user_found, user_institution
    FROM "users" u WHERE u."id" = NEW."user_id";
  IF user_found IS NOT TRUE THEN
    RAISE EXCEPTION '% user % not found or not visible', TG_TABLE_NAME, NEW."user_id"
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF NEW."institution_id" IS DISTINCT FROM user_institution THEN
    RAISE EXCEPTION '% institution_id does not match the user''s institution', TG_TABLE_NAME
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "sessions_user_institution_trg"
  BEFORE INSERT OR UPDATE OF "institution_id", "user_id" ON "sessions"
  FOR EACH ROW EXECUTE FUNCTION "igaro_enforce_user_institution"();
CREATE TRIGGER "password_resets_user_institution_trg"
  BEFORE INSERT OR UPDATE OF "institution_id", "user_id" ON "password_resets"
  FOR EACH ROW EXECUTE FUNCTION "igaro_enforce_user_institution"();

