-- PART 3: application role (no login, no password in this repository).
--
-- The migration creates `igaro_app` as NOLOGIN. To let the API/worker connect, run once per
-- environment, outside version control:
--     ALTER ROLE igaro_app WITH LOGIN PASSWORD '<secret from your secret store>';
-- and point the API/worker DATABASE_URL at igaro_app. Keep a separate owner/migrator
-- connection (the role that runs `prisma migrate`) for migrations only.
-- ===========================================================================

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'igaro_app') THEN
    CREATE ROLE "igaro_app" NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
  END IF;
END
$$;

DO $$
BEGIN
  EXECUTE format('GRANT USAGE ON SCHEMA %I TO "igaro_app"', current_schema());
END
$$;

-- ===========================================================================
-- PART 4: row level security.
--
-- Session settings (set with SET LOCAL / set_config(..., true) inside a transaction):
--   app.institution_id        tenant scope; set by the data-access layer from the session
--   app.is_platform_admin     'true' = platform scope (set only for authenticated platform admins
--                             and trusted background jobs)
--   Narrow single-row lookups for unauthenticated paths (the value must equal the column):
--   app.institution_slug      institutions.slug            (public keys.json)
--   app.verification_token    credentials.verification_token (public verification)
--   app.holder_token_hash     credentials.holder_token_hash  (holder page)
--   app.login_email           users.email                  (login, password reset request)
--   app.session_token_hash    sessions.token_hash          (session lookup)
--   app.invite_token_hash     invites.token_hash           (invite accept)
--   app.reset_token_hash      password_resets.token_hash   (password reset)
-- After such a lookup the API sets app.institution_id from the row it found.
-- Unset or empty settings never match. FORCE ROW LEVEL SECURITY makes the policies apply to
-- a non-superuser table owner too. Superusers and BYPASSRLS roles always skip RLS (igaro_app
-- has neither), so never run the application as a superuser.
-- Anyone able to run arbitrary SQL as igaro_app can set these settings (see threat-model.md, M2).
-- ===========================================================================

CREATE FUNCTION "app_institution_id"() RETURNS uuid
LANGUAGE sql STABLE AS $$
  SELECT NULLIF(current_setting('app.institution_id', true), '')::uuid
$$;

CREATE FUNCTION "app_is_platform_admin"() RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT COALESCE(current_setting('app.is_platform_admin', true), '') = 'true'
$$;

CREATE FUNCTION "app_lookup"(setting text) RETURNS text
LANGUAGE sql STABLE AS $$
  SELECT NULLIF(current_setting(setting, true), '')
$$;

GRANT EXECUTE ON FUNCTION "app_institution_id"(), "app_is_platform_admin"(), "app_lookup"(text)
  TO "igaro_app";

ALTER TABLE "institutions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "institutions" FORCE ROW LEVEL SECURITY;
ALTER TABLE "institution_keys" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "institution_keys" FORCE ROW LEVEL SECURITY;
ALTER TABLE "users" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "users" FORCE ROW LEVEL SECURITY;
ALTER TABLE "sessions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "sessions" FORCE ROW LEVEL SECURITY;
ALTER TABLE "invites" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "invites" FORCE ROW LEVEL SECURITY;
ALTER TABLE "password_resets" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "password_resets" FORCE ROW LEVEL SECURITY;
ALTER TABLE "credential_types" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "credential_types" FORCE ROW LEVEL SECURITY;
ALTER TABLE "credential_holders" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "credential_holders" FORCE ROW LEVEL SECURITY;
ALTER TABLE "credentials" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "credentials" FORCE ROW LEVEL SECURITY;
ALTER TABLE "credential_events" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "credential_events" FORCE ROW LEVEL SECURITY;
ALTER TABLE "verification_logs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "verification_logs" FORCE ROW LEVEL SECURITY;
ALTER TABLE "audit_logs" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "audit_logs" FORCE ROW LEVEL SECURITY;
ALTER TABLE "audit_head_hashes" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "audit_head_hashes" FORCE ROW LEVEL SECURITY;
ALTER TABLE "import_batches" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "import_batches" FORCE ROW LEVEL SECURITY;
ALTER TABLE "import_rows" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "import_rows" FORCE ROW LEVEL SECURITY;

-- institutions: the tenant sees/updates its own row; platform has full access; public slug lookup.
CREATE POLICY "institutions_tenant_select" ON "institutions" FOR SELECT
  USING ("id" = app_institution_id());
CREATE POLICY "institutions_tenant_update" ON "institutions" FOR UPDATE
  USING ("id" = app_institution_id()) WITH CHECK ("id" = app_institution_id());
CREATE POLICY "institutions_platform" ON "institutions" FOR ALL
  USING (app_is_platform_admin()) WITH CHECK (app_is_platform_admin());
CREATE POLICY "institutions_slug_lookup" ON "institutions" FOR SELECT
  USING ("slug" = app_lookup('app.institution_slug'));

-- institution_keys: the tenant may only READ its keys. Creating keys and changing their status
-- (rotation, compromise) is platform scope only; column grants further limit platform UPDATEs
-- to status/retired_at.
CREATE POLICY "institution_keys_tenant_read" ON "institution_keys" FOR SELECT
  USING ("institution_id" = app_institution_id());
CREATE POLICY "institution_keys_platform" ON "institution_keys" FOR ALL
  USING (app_is_platform_admin()) WITH CHECK (app_is_platform_admin());

-- invites: tenant full access; platform full access (first-admin invite).

CREATE POLICY "invites_tenant" ON "invites" FOR ALL
  USING ("institution_id" = app_institution_id()) WITH CHECK ("institution_id" = app_institution_id());
CREATE POLICY "invites_platform" ON "invites" FOR ALL
  USING (app_is_platform_admin()) WITH CHECK (app_is_platform_admin());
CREATE POLICY "invites_token_lookup" ON "invites" FOR SELECT
  USING ("token_hash" = app_lookup('app.invite_token_hash'));

-- users, sessions, password_resets: tenant rows, platform (incl. NULL institution), narrow lookups.
CREATE POLICY "users_tenant" ON "users" FOR ALL
  USING ("institution_id" = app_institution_id()) WITH CHECK ("institution_id" = app_institution_id());
CREATE POLICY "users_platform" ON "users" FOR ALL
  USING (app_is_platform_admin()) WITH CHECK (app_is_platform_admin());
CREATE POLICY "users_login_lookup" ON "users" FOR SELECT
  USING ("email" = app_lookup('app.login_email'));

CREATE POLICY "sessions_tenant" ON "sessions" FOR ALL
  USING ("institution_id" = app_institution_id()) WITH CHECK ("institution_id" = app_institution_id());
CREATE POLICY "sessions_platform" ON "sessions" FOR ALL
  USING (app_is_platform_admin()) WITH CHECK (app_is_platform_admin());
CREATE POLICY "sessions_token_lookup" ON "sessions" FOR SELECT
  USING ("token_hash" = app_lookup('app.session_token_hash'));

CREATE POLICY "password_resets_tenant" ON "password_resets" FOR ALL
  USING ("institution_id" = app_institution_id()) WITH CHECK ("institution_id" = app_institution_id());
CREATE POLICY "password_resets_platform" ON "password_resets" FOR ALL
  USING (app_is_platform_admin()) WITH CHECK (app_is_platform_admin());
CREATE POLICY "password_resets_token_lookup" ON "password_resets" FOR SELECT
  USING ("token_hash" = app_lookup('app.reset_token_hash'));

-- Issuance data: tenant full access; platform admins read only (they never issue).
CREATE POLICY "credential_types_tenant" ON "credential_types" FOR ALL
  USING ("institution_id" = app_institution_id()) WITH CHECK ("institution_id" = app_institution_id());
CREATE POLICY "credential_types_platform_read" ON "credential_types" FOR SELECT
  USING (app_is_platform_admin());

CREATE POLICY "credential_holders_tenant" ON "credential_holders" FOR ALL
  USING ("institution_id" = app_institution_id()) WITH CHECK ("institution_id" = app_institution_id());
CREATE POLICY "credential_holders_platform_read" ON "credential_holders" FOR SELECT
  USING (app_is_platform_admin());

CREATE POLICY "credentials_tenant" ON "credentials" FOR ALL
  USING ("institution_id" = app_institution_id()) WITH CHECK ("institution_id" = app_institution_id());
CREATE POLICY "credentials_platform_read" ON "credentials" FOR SELECT
  USING (app_is_platform_admin());
CREATE POLICY "credentials_token_lookup" ON "credentials" FOR SELECT
  USING (
    "verification_token" = app_lookup('app.verification_token')
    OR "holder_token_hash" = app_lookup('app.holder_token_hash')
  );

CREATE POLICY "credential_events_tenant" ON "credential_events" FOR ALL
  USING ("institution_id" = app_institution_id()) WITH CHECK ("institution_id" = app_institution_id());
CREATE POLICY "credential_events_platform_read" ON "credential_events" FOR SELECT
  USING (app_is_platform_admin());

CREATE POLICY "import_batches_tenant" ON "import_batches" FOR ALL
  USING ("institution_id" = app_institution_id()) WITH CHECK ("institution_id" = app_institution_id());
CREATE POLICY "import_batches_platform_read" ON "import_batches" FOR SELECT
  USING (app_is_platform_admin());

CREATE POLICY "import_rows_tenant" ON "import_rows" FOR ALL
  USING ("institution_id" = app_institution_id()) WITH CHECK ("institution_id" = app_institution_id());
CREATE POLICY "import_rows_platform_read" ON "import_rows" FOR SELECT
  USING (app_is_platform_admin());

-- verification_logs: written by the public verify path (institution may be unknown = NULL).
CREATE POLICY "verification_logs_select" ON "verification_logs" FOR SELECT
  USING ("institution_id" = app_institution_id() OR app_is_platform_admin());
CREATE POLICY "verification_logs_insert" ON "verification_logs" FOR INSERT
  WITH CHECK (
    "institution_id" IS NULL
    OR "institution_id" = app_institution_id()
    OR app_is_platform_admin()
  );

-- audit_logs / audit_head_hashes: the tenant reads and appends to its own chain; platform scope
-- reads everything and appends to any chain (including the NULL platform chain).
CREATE POLICY "audit_logs_select" ON "audit_logs" FOR SELECT
  USING ("institution_id" = app_institution_id() OR app_is_platform_admin());
CREATE POLICY "audit_logs_insert" ON "audit_logs" FOR INSERT
  WITH CHECK ("institution_id" = app_institution_id() OR app_is_platform_admin());

CREATE POLICY "audit_head_hashes_select" ON "audit_head_hashes" FOR SELECT
  USING ("institution_id" = app_institution_id() OR app_is_platform_admin());
CREATE POLICY "audit_head_hashes_insert" ON "audit_head_hashes" FOR INSERT
  WITH CHECK ("institution_id" = app_institution_id() OR app_is_platform_admin());

-- ===========================================================================
-- PART 5: least-privilege grants for igaro_app. Tables are created without PUBLIC grants.
-- No DELETE on credentials (never deleted); audit_logs, audit_head_hashes, credential_events,
-- verification_logs are INSERT+SELECT only. (T-006 adds the triggers that harden the rest.)
-- ===========================================================================

-- UPDATE is granted per column only. Identity columns (id, institution_id, kid, slug, email,
-- credential_number, tokens' identity, signed credential columns, created_at) are never updatable.
GRANT SELECT, INSERT ON "institutions" TO "igaro_app";
GRANT UPDATE ("name", "logo_key", "primary_color", "secondary_color", "card_title", "public_fields", "status", "updated_at")
  ON "institutions" TO "igaro_app";
GRANT SELECT, INSERT ON "institution_keys" TO "igaro_app";
GRANT UPDATE ("status", "retired_at") ON "institution_keys" TO "igaro_app";
GRANT SELECT, INSERT ON "users" TO "igaro_app";
GRANT UPDATE ("name", "password_hash", "status", "updated_at") ON "users" TO "igaro_app";
GRANT SELECT, INSERT, DELETE ON "sessions" TO "igaro_app";
GRANT SELECT, INSERT ON "invites" TO "igaro_app";
GRANT UPDATE ("token_hash", "expires_at", "used_at") ON "invites" TO "igaro_app";
GRANT SELECT, INSERT ON "password_resets" TO "igaro_app";
GRANT UPDATE ("used_at") ON "password_resets" TO "igaro_app";
GRANT SELECT, INSERT, DELETE ON "credential_types" TO "igaro_app";
GRANT UPDATE ("name", "attribute_schema", "validity_days", "updated_at") ON "credential_types" TO "igaro_app";
GRANT SELECT, INSERT, DELETE ON "credential_holders" TO "igaro_app";
GRANT UPDATE ("full_name", "external_id", "email", "photo_key", "photo_sha256", "updated_at")
  ON "credential_holders" TO "igaro_app";
GRANT SELECT, INSERT ON "credentials" TO "igaro_app";
GRANT UPDATE ("status", "superseded_by", "holder_token_hash", "anchor_status", "updated_at")
  ON "credentials" TO "igaro_app";
GRANT SELECT, INSERT ON "credential_events" TO "igaro_app";
GRANT SELECT, INSERT ON "verification_logs" TO "igaro_app";
GRANT SELECT, INSERT ON "audit_logs" TO "igaro_app";
GRANT SELECT, INSERT ON "audit_head_hashes" TO "igaro_app";
GRANT SELECT, INSERT ON "import_batches" TO "igaro_app";
GRANT UPDATE ("source_key", "status", "total_rows", "imported_rows", "error_rows", "completed_at")
  ON "import_batches" TO "igaro_app";
GRANT SELECT, INSERT, DELETE ON "import_rows" TO "igaro_app";
GRANT UPDATE ("status", "error", "credential_id") ON "import_rows" TO "igaro_app";

-- ===========================================================================
-- PART 6: guard triggers for key and institution status.
-- ===========================================================================

-- institutions.status may only be changed in platform scope (tenant admins can update branding).
CREATE FUNCTION "igaro_guard_institution_status"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT app_is_platform_admin() THEN
    RAISE EXCEPTION 'institution status can only be changed in platform scope'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER "institutions_guard_status_trg"
  BEFORE UPDATE ON "institutions"
  FOR EACH ROW EXECUTE FUNCTION "igaro_guard_institution_status"();

-- institution_keys: key material and identity are immutable; COMPROMISED is a terminal status.
CREATE FUNCTION "igaro_guard_institution_key"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."id" IS DISTINCT FROM OLD."id"
     OR NEW."institution_id" IS DISTINCT FROM OLD."institution_id"
     OR NEW."kid" IS DISTINCT FROM OLD."kid"
     OR NEW."algorithm" IS DISTINCT FROM OLD."algorithm"
     OR NEW."public_key" IS DISTINCT FROM OLD."public_key"
     OR NEW."encrypted_private_key" IS DISTINCT FROM OLD."encrypted_private_key"
     OR NEW."created_at" IS DISTINCT FROM OLD."created_at" THEN
    RAISE EXCEPTION 'institution key identity and key material are immutable'
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."status" = 'COMPROMISED' AND NEW."status" IS DISTINCT FROM OLD."status" THEN
    RAISE EXCEPTION 'COMPROMISED key status is final'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER "institution_keys_guard_trg"
  BEFORE UPDATE ON "institution_keys"
  FOR EACH ROW EXECUTE FUNCTION "igaro_guard_institution_key"();
